public class AbstractCategoryItemRenderer_getLegendItems_TriageGen0Test {

    @Spy
    private AbstractCategoryItemRenderer renderer;

    @Spy
    private CategoryPlot plot;

    @Spy
    private CategoryDataset dataset;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        doReturn(plot).when(renderer).getPlot();
    }

    @Test
    public void testGetLegendItems_NullDataset() {
        when(plot.getIndexOf(renderer)).thenReturn(0);
        when(plot.getDataset(0)).thenReturn(null);

        LegendItemCollection result = renderer.getLegendItems();

        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_AscendingOrder_WithItems() {
        int datasetIndex = 0;
        int seriesCount = 3;

        when(plot.getIndexOf(renderer)).thenReturn(datasetIndex);
        when(plot.getDataset(datasetIndex)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(seriesCount);

        // Mock visibility and items
        // Series 0: Visible, has item
        // Series 1: Invisible
        // Series 2: Visible, has item
        doReturn(true).when(renderer).isSeriesVisibleInLegend(0);
        doReturn(false).when(renderer).isSeriesVisibleInLegend(1);
        doReturn(true).when(renderer).isSeriesVisibleInLegend(2);

        LegendItem item0 = mock(LegendItem.class);
        LegendItem item2 = mock(LegendItem.class);
        doReturn(item0).when(renderer).getLegendItem(datasetIndex, 0);
        doReturn(null).when(renderer).getLegendItem(datasetIndex, 1);
        doReturn(item2).when(renderer).getLegendItem(datasetIndex, 2);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(2, result.size());
        assertEquals(item0, result.getItem(0));
        assertEquals(item2, result.getItem(1));
    }

    @Test
    public void testGetLegendItems_DescendingOrder_WithItems() {
        int datasetIndex = 0;
        int seriesCount = 3;

        when(plot.getIndexOf(renderer)).thenReturn(datasetIndex);
        when(plot.getDataset(datasetIndex)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.DESCENDING);
        when(dataset.getRowCount()).thenReturn(seriesCount);

        // Mock visibility
        doReturn(true).when(renderer).isSeriesVisibleInLegend(0);
        doReturn(true).when(renderer).isSeriesVisibleInLegend(1);
        doReturn(true).when(renderer).isSeriesVisibleInLegend(2);

        LegendItem item0 = mock(LegendItem.class);
        LegendItem item1 = mock(LegendItem.class);
        LegendItem item2 = mock(LegendItem.class);

        doReturn(item0).when(renderer).getLegendItem(datasetIndex, 0);
        doReturn(item1).when(renderer).getLegendItem(datasetIndex, 1);
        doReturn(item2).when(renderer).getLegendItem(datasetIndex, 2);

        LegendItemCollection result = renderer.getLegendItems();

        // In descending order, index 2 should be first, then 1, then 0
        assertEquals(3, result.size());
        assertEquals(item2, result.getItem(0));
        assertEquals(item1, result.getItem(1));
        assertEquals(item0, result.getItem(2));
    }

    @Test
    public void testGetLegendItems_EmptyDataset() {
        int datasetIndex = 0;
        when(plot.getIndexOf(renderer)).thenReturn(datasetIndex);
        when(plot.getDataset(datasetIndex)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(0);

        LegendItemCollection result = renderer.getLegendItems();

        assertNotNull(result);
        assertEquals(0, result.size());
    }

    @Test
    public void testGetLegendItems_VisibleButNullItem() {
        int datasetIndex = 0;
        when(plot.getIndexOf(renderer)).thenReturn(datasetIndex);
        when(plot.getDataset(datasetIndex)).thenReturn(dataset);
        when(plot.getRowRenderingOrder()).thenReturn(SortOrder.ASCENDING);
        when(dataset.getRowCount()).thenReturn(1);

        doReturn(true).when(renderer).isSeriesVisibleInLegend(0);
        doReturn(null).when(renderer).getLegendItem(datasetIndex, 0);

        LegendItemCollection result = renderer.getLegendItems();

        assertEquals(0, result.size());
    }
}
